CREATE SCHEMA "auth";

CREATE SCHEMA "customer";

CREATE SCHEMA "inventory";

CREATE SCHEMA "promotion";

CREATE SCHEMA "sales";

CREATE TABLE "auth"."account" (
  "account_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_name" varchar(255),
  "account_email" varchar(255) UNIQUE NOT NULL,
  "account_phone_number" varchar(20),
  "account_date_of_birth" date,
  "account_house_number" varchar(255),
  "account_ward" varchar(100),
  "account_city" varchar(255),
  "account_country" varchar(100),
  "account_hash_password" varchar(255),
  "account_status" varchar(50),
  "account_role_name" varchar(255)
);

CREATE TABLE "customer"."customer" (
  "customer_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int UNIQUE NOT NULL,
  "customer_name" varchar(255),
  "customer_phone_number" varchar(20),
  "customer_house_number" varchar(255),
  "customer_ward" varchar(100),
  "customer_city" varchar(255),
  "customer_country" varchar(100)
);

CREATE TABLE "customer"."wishlist_item" (
  "wishlist_item_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "wishlist_item_account_id" int NOT NULL,
  "wishlist_item_product_id" int NOT NULL
);

CREATE TABLE "inventory"."category" (
  "category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_name" varchar(255)
);

CREATE TABLE "inventory"."collection" (
  "collection_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "collection_name" varchar(255)
);

CREATE TABLE "inventory"."gender" (
  "gender_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gender_name" varchar(50)
);

CREATE TABLE "inventory"."size" (
  "size_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "size_name" varchar(50)
);

CREATE TABLE "inventory"."color" (
  "color_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "color_name" varchar(50)
);

CREATE TABLE "inventory"."product" (
  "product_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_name" varchar(255) NOT NULL,
  "product_description" text,
  "product_total_score_review" decimal(3,2) DEFAULT 0,
  "product_status" varchar(50),
  "product_updated_at" datetime,
  "product_category_id" int,
  "product_gender_id" int,
  "product_promotion_id" int
);

CREATE TABLE "inventory"."product_collection" (
  "product_collection_product_id" int,
  "product_collection_collection_id" int,
  PRIMARY KEY ("product_collection_product_id", "product_collection_collection_id")
);

CREATE TABLE "inventory"."variant" (
  "variant_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_quantity" int DEFAULT 0,
  "variant_sell_price" decimal(12,2),
  "variant_status" varchar(50),
  "variant_product_id" int NOT NULL,
  "variant_size_id" int,
  "variant_color_id" int
);

CREATE TABLE "inventory"."gallery" (
  "gallery_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gallery_product_id" int,
  "gallery_order_no" int,
  "gallery_uri" varchar(255)
);

CREATE TABLE "inventory"."supplier" (
  "supplier_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "supplier_name" varchar(255)
);

CREATE TABLE "inventory"."goods_receipt" (
  "goods_receipt_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "goods_receipt_final_price" decimal(12,2),
  "goods_receipt_status" varchar(50),
  "goods_receipt_created_date" datetime,
  "goods_receipt_supplier_id" int,
  "goods_receipt_account_id" int
);

CREATE TABLE "inventory"."goods_receipt_detail" (
  "goods_receipt_detail_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "goods_receipt_detail_actual_unit_price" decimal(12,2),
  "goods_receipt_detail_quantity" int,
  "goods_receipt_detail_total_price" decimal(12,2),
  "goods_receipt_detail_goods_receipt_id" int NOT NULL,
  "goods_receipt_detail_variant_id" int NOT NULL
);

CREATE TABLE "promotion"."promotion" (
  "promotion_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "promotion_type" varchar(50),
  "promotion_quantity" int,
  "promotion_used_amount" int DEFAULT 0,
  "promotion_start_date" datetime,
  "promotion_end_date" datetime,
  "promotion_status" varchar(50)
);

CREATE TABLE "promotion"."product_promotion" (
  "promotion_id" int PRIMARY KEY,
  "product_promotion_discount_percentage" decimal(5,2)
);

CREATE TABLE "promotion"."order_promotion" (
  "promotion_id" int PRIMARY KEY,
  "order_promotion_discount_percentage" decimal(5,2),
  "order_promotion_thresh_price" decimal(12,2)
);

CREATE TABLE "promotion"."code_promotion" (
  "promotion_id" int PRIMARY KEY,
  "code_promotion_code" varchar(50) UNIQUE NOT NULL,
  "code_promotion_discount_percentage" decimal(5,2),
  "code_promotion_thresh_price" decimal(12,2)
);

CREATE TABLE "sales"."payment" (
  "payment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "payment_name" varchar(100)
);

CREATE TABLE "sales"."order" (
  "order_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_customer_name" varchar(255),
  "order_customer_phone_number" varchar(20),
  "order_customer_house_number" varchar(255),
  "order_customer_ward" varchar(100),
  "order_customer_city" varchar(255),
  "order_customer_country" varchar(100),
  "order_discount_amount" decimal(12,2),
  "order_shipping_fee" decimal(12,2),
  "order_total_price" decimal(12,2),
  "order_payment_status" varchar(50),
  "order_status" varchar(50),
  "order_created_date" datetime,
  "order_account_id" int,
  "order_payment_id" int,
  "order_promotion_id" int
);

CREATE TABLE "sales"."order_detail" (
  "order_detail_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_detail_unit_price" decimal(12,2),
  "order_detail_quantity" int,
  "order_detail_order_id" int NOT NULL,
  "order_detail_variant_id" int NOT NULL,
  "order_detail_product_promotion_id" int
);

CREATE TABLE "sales"."invoice" (
  "invoice_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "invoice_order_id" int UNIQUE NOT NULL,
  "invoice_snapshot_json" json,
  "invoice_created_date" datetime
);

CREATE TABLE "sales"."order_status_history" (
  "order_status_history_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_status_history_order_id" int NOT NULL,
  "order_status_history_from_value" varchar(50),
  "order_status_history_to_value" varchar(50),
  "order_status_history_source" varchar(50),
  "order_status_history_changed_by" int,
  "order_status_history_changed_time" datetime
);

CREATE TABLE "sales"."cart" (
  "cart_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cart_account_id" int UNIQUE NOT NULL
);

CREATE TABLE "sales"."cart_item" (
  "cart_item_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cart_item_quantity" int DEFAULT 1,
  "cart_item_cart_id" int NOT NULL,
  "cart_item_variant_id" int NOT NULL
);

CREATE UNIQUE INDEX ON "customer"."wishlist_item" ("wishlist_item_account_id", "wishlist_item_product_id");

CREATE UNIQUE INDEX ON "sales"."cart_item" ("cart_item_cart_id", "cart_item_variant_id");

COMMENT ON COLUMN "inventory"."product"."product_promotion_id" IS 'Product (0,1) - Product Promotion (0,n)';

COMMENT ON COLUMN "inventory"."goods_receipt"."goods_receipt_account_id" IS 'Account creates goods receipt';

COMMENT ON COLUMN "promotion"."promotion"."promotion_type" IS 'PRODUCT | ORDER | CODE';

COMMENT ON COLUMN "sales"."payment"."payment_name" IS 'Payment method';

COMMENT ON COLUMN "sales"."order"."order_account_id" IS 'Account creates order';

COMMENT ON COLUMN "sales"."order"."order_promotion_id" IS 'Order (0,1) - Promotion (0,n)';

COMMENT ON COLUMN "sales"."order_detail"."order_detail_product_promotion_id" IS 'Order Detail (0,1) - Product Promotion (0,n)';

COMMENT ON COLUMN "sales"."invoice"."invoice_order_id" IS 'Order (0,1) - Invoice (1,1)';

COMMENT ON COLUMN "sales"."invoice"."invoice_snapshot_json" IS 'Snapshot at invoicing time: product name, original unit price,
discounted unit price, quantity, discount amount, shipping fee,
final price, address, orderer, phone number, email, payment method
';

ALTER TABLE "inventory"."product" ADD FOREIGN KEY ("product_category_id") REFERENCES "inventory"."category" ("category_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."product" ADD FOREIGN KEY ("product_gender_id") REFERENCES "inventory"."gender" ("gender_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."product" ADD FOREIGN KEY ("product_promotion_id") REFERENCES "promotion"."product_promotion" ("promotion_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."product_collection" ADD FOREIGN KEY ("product_collection_product_id") REFERENCES "inventory"."product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."product_collection" ADD FOREIGN KEY ("product_collection_collection_id") REFERENCES "inventory"."collection" ("collection_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."variant" ADD FOREIGN KEY ("variant_product_id") REFERENCES "inventory"."product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."variant" ADD FOREIGN KEY ("variant_size_id") REFERENCES "inventory"."size" ("size_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."variant" ADD FOREIGN KEY ("variant_color_id") REFERENCES "inventory"."color" ("color_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."gallery" ADD FOREIGN KEY ("gallery_product_id") REFERENCES "inventory"."product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."goods_receipt" ADD FOREIGN KEY ("goods_receipt_supplier_id") REFERENCES "inventory"."supplier" ("supplier_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."goods_receipt" ADD FOREIGN KEY ("goods_receipt_account_id") REFERENCES "auth"."account" ("account_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."goods_receipt_detail" ADD FOREIGN KEY ("goods_receipt_detail_goods_receipt_id") REFERENCES "inventory"."goods_receipt" ("goods_receipt_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory"."goods_receipt_detail" ADD FOREIGN KEY ("goods_receipt_detail_variant_id") REFERENCES "inventory"."variant" ("variant_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "promotion"."product_promotion" ADD FOREIGN KEY ("promotion_id") REFERENCES "promotion"."promotion" ("promotion_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "promotion"."order_promotion" ADD FOREIGN KEY ("promotion_id") REFERENCES "promotion"."promotion" ("promotion_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "promotion"."code_promotion" ADD FOREIGN KEY ("promotion_id") REFERENCES "promotion"."promotion" ("promotion_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order" ADD FOREIGN KEY ("order_account_id") REFERENCES "auth"."account" ("account_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order" ADD FOREIGN KEY ("order_payment_id") REFERENCES "sales"."payment" ("payment_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order" ADD FOREIGN KEY ("order_promotion_id") REFERENCES "promotion"."promotion" ("promotion_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order_detail" ADD FOREIGN KEY ("order_detail_order_id") REFERENCES "sales"."order" ("order_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order_detail" ADD FOREIGN KEY ("order_detail_variant_id") REFERENCES "inventory"."variant" ("variant_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order_detail" ADD FOREIGN KEY ("order_detail_product_promotion_id") REFERENCES "promotion"."product_promotion" ("promotion_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."invoice" ADD FOREIGN KEY ("invoice_order_id") REFERENCES "sales"."order" ("order_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order_status_history" ADD FOREIGN KEY ("order_status_history_order_id") REFERENCES "sales"."order" ("order_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."order_status_history" ADD FOREIGN KEY ("order_status_history_changed_by") REFERENCES "auth"."account" ("account_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."cart" ADD FOREIGN KEY ("cart_account_id") REFERENCES "customer"."customer" ("customer_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."cart_item" ADD FOREIGN KEY ("cart_item_cart_id") REFERENCES "sales"."cart" ("cart_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sales"."cart_item" ADD FOREIGN KEY ("cart_item_variant_id") REFERENCES "inventory"."variant" ("variant_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "customer"."wishlist_item" ADD FOREIGN KEY ("wishlist_item_account_id") REFERENCES "auth"."account" ("account_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "customer"."wishlist_item" ADD FOREIGN KEY ("wishlist_item_product_id") REFERENCES "inventory"."product" ("product_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "auth"."account" ADD FOREIGN KEY ("account_id") REFERENCES "customer"."customer" ("account_id") DEFERRABLE INITIALLY IMMEDIATE;
